mapper.sql:
, collection AS ( SELECT q.id question_id,q.bank_id question_bank_id,s.id subject_id,s.name subject_name,b.name question_bank_name, r.stem,r.type,() available,(latest.question_id IS NOT NULL) practiced, saved.created_atlatest.submitted_at created_at, latest.submitted_at last_practiced_at,coalesce(latest.judgment,'') last_outcome,coalesce(t.right_count,0) right_count,coalesce(t.wrong_count,0) wrong_count FROM question q JOIN question_bank b ON b.id=q.bank_id JOIN subject s ON s.id=b.subject_id JOIN question_revision r ON r.id=q.current_revision_id LEFT JOIN facts latest ON latest.question_id=q.id AND latest.rn=1 LEFT JOIN totals t ON t.question_id=q.id
JOIN user_favorite saved ON saved.question_id=q.id AND saved.user_id=#{userId} WHERE t.wrong_count>0 AND latest.judgment='WRONG'AND latest.judgment='CORRECT'
)

mapper.select:
 SELECT * FROM collection  ORDER BY
wrong_count DESC,last_practiced_at DESC,question_idcreated_at ASC,question_idcreated_at DESC,question_id
LIMIT #{limit} OFFSET #{offset}
